package io.github.ranger3462.dungeondelving.forging;

import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.storage.loot.LootContext;
import net.minecraft.world.level.storage.loot.predicates.LootItemCondition;
import net.neoforged.neoforge.common.loot.IGlobalLootModifier;
import net.neoforged.neoforge.common.loot.LootModifier;

/**
 * Gives gear generated by any loot table its ★ (DD-89): rolled by the dungeon's tier in dungeon chests and boss drops,
 * ★3 anywhere else (see {@link Quality#lootStars}). Registered for all loot tables in
 * {@code data/neoforge/loot_modifiers/global_loot_modifiers.json}.
 */
public class GearStarsLootModifier extends LootModifier {
    public static final MapCodec<GearStarsLootModifier> CODEC =
            RecordCodecBuilder.mapCodec(instance -> codecStart(instance).apply(instance, GearStarsLootModifier::new));

    public GearStarsLootModifier(LootItemCondition[] conditions) {
        super(conditions);
    }

    @Override
    protected ObjectArrayList<ItemStack> doApply(ObjectArrayList<ItemStack> generatedLoot, LootContext context) {
        for (ItemStack stack : generatedLoot) {
            if (Quality.isGear(stack)) {
                Quality.stamp(stack, Quality.lootStars(context.getQueriedLootTableId(), context.getRandom()));
            }
        }
        return generatedLoot;
    }

    @Override
    public MapCodec<? extends IGlobalLootModifier> codec() {
        return CODEC;
    }
}
